26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    /**
61	     * Pragmatic check for a syntactically valid email address: a non-empty local
62	     * part, a single '@', and a domain with at least one dot-separated label.
63	     */
64	    private static final Pattern EMAIL_PATTERN =
65	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
66	
67	    /**
68	     * Common street-type abbreviations expanded during address normalization,
69	     * keyed by their upper-cased form.
70	     */
71	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
72	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
73	
74	    private final ClinicService clinicService;
75	
76	    private final OwnerMapper ownerMapper;
77	
78	    private final PetMapper petMapper;
79	
80	    private final VisitMapper visitMapper;
81	
82	    public OwnerRestControllerV1(ClinicService clinicService,
83	                                 OwnerMapper ownerMapper,
84	                                 PetMapper petMapper,
85	                                 VisitMapper visitMapper) {
86	        this.clinicService = clinicService;
87	        this.ownerMapper = ownerMapper;
88	        this.petMapper = petMapper;
89	        this.visitMapper = visitMapper;
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
95	        Collection<Owner> owners;
96	        if (lastName != null) {
97	            owners = this.clinicService.findOwnerByLastName(lastName);
98	        } else {
99	            owners = this.clinicService.findAllOwners();
100	        }
101	        if (owners.isEmpty()) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
110	        Owner owner = this.clinicService.findOwnerById(ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        // Validate & normalize the optional email; reject the create when it is present but invalid.
121	        if (!normalizeEmail(ownerFieldsDto)) {
122	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	        }
124	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
125	        // abbreviations) and store the normalized form back on the DTO so it is what gets
126	        // persisted and compared. Reject the create when the address is blank once normalized.
127	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
128	        if (canonicalAddress.isBlank()) {
129	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
130	        }
131	        ownerFieldsDto.setAddress(canonicalAddress);
132	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
133	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
134	        if (normalizedTelephone == null) {
135	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
136	        }
137	        // Reject the create if any existing owner already uses this telephone (compared in E.164 form).
138	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
139	            .map(Owner::getTelephone)
140	            .map(OwnerRestControllerV1::toE164)
141	            .filter(existing -> existing != null)
142	            .anyMatch(normalizedTelephone::equals);
143	        if (telephoneInUse) {
144	            return new ResponseEntity<>(HttpStatus.CONFLICT);
145	        }
146	        // Reject the create when another owner already shares this owner's last name and address
147	        // (compared case-insensitively with collapsed whitespace), unless the request opts into
148	        // sharing a household.
149	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
150	            String normalizedLastName = normalizeHouseholdKey(ownerFieldsDto.getLastName());
151	            String normalizedAddress = normalizeHouseholdKey(ownerFieldsDto.getAddress());
152	            boolean householdInUse = this.clinicService.findAllOwners().stream()
153	                .anyMatch(existing ->
154	                    normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
155	                        && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress));
156	            if (householdInUse) {
157	                return new ResponseEntity<>(HttpStatus.CONFLICT);
158	            }
159	        }
160	        ownerFieldsDto.setTelephone(normalizedTelephone);
161	        HttpHeaders headers = new HttpHeaders();
162	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
163	        // Default the registration date to the server's current date when none was supplied.
164	        if (owner.getRegistrationDate() == null) {
165	            owner.setRegistrationDate(LocalDate.now());
166	        }
167	        // Assign the customer code as '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three
168	        // letters of the city, the upper-cased first three letters of the last name, and a
169	        // per-city 4-digit sequence one greater than the number of owners already in that city.
170	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
171	        // Record how many existing owners already share this owner's first and last name
172	        // (compared case-insensitively) at the moment before this owner is created.
173	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
174	        this.clinicService.saveOwner(owner);
175	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
176	        headers.setLocation(UriComponentsBuilder.newInstance()
177	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
178	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
179	    }
180	
181	    /**
182	     * Validate and normalize the optional owner email in place.
183	     *
184	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
185	     * When present it must be a syntactically valid address; a valid address is
186	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
187	     * present but syntactically invalid, so the caller can reject with 400.
188	     */
189	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
190	        String email = ownerFieldsDto.getEmail();
191	        if (email == null || email.isBlank()) {
192	            ownerFieldsDto.setEmail(null);
193	            return true;
194	        }
195	        String normalized = email.trim().toLowerCase(Locale.ROOT);
196	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
197	            return false;
198	        }
199	        ownerFieldsDto.setEmail(normalized);
200	        return true;
201	    }
202	
203	    /**
204	     * Normalize an owner address: trim, collapse each run of whitespace to a single
205	     * space, upper-case, and expand common street-type abbreviations
206	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
207	     * A {@code null} value normalizes to the empty string.
208	     */
209	    private static String normalizeAddress(String value) {
210	        if (value == null) {
211	            return "";
212	        }
213	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
214	        if (collapsed.isEmpty()) {
215	            return "";
216	        }
217	        String[] tokens = collapsed.split(" ");
218	        StringBuilder sb = new StringBuilder(collapsed.length());
219	        for (int i = 0; i < tokens.length; i++) {
220	            if (i > 0) {
221	                sb.append(' ');
222	            }
223	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
224	        }
225	        return sb.toString();
226	    }
227	
228	    /**
229	     * Normalize an owner household field (last name or address) for duplicate detection:
230	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
231	     * A {@code null} value normalizes to the empty string.
232	     */
233	    private static String normalizeHouseholdKey(String value) {
234	        if (value == null) {
235	            return "";
236	        }
237	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
238	    }
239	
240	    /**
241	     * Normalize a telephone number to E.164 form.
242	     *
243	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
244	     * explicit leading {@code '+'} and country code it is kept; otherwise the
245	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
246	     * dropped from the national digits. The result must contain 8 to 15 digits
247	     * after the {@code '+'}.
248	     *
249	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
250	     *         the input is absent or cannot form a valid E.164 number.
251	     */
252	    private static String toE164(String raw) {
253	        if (raw == null) {
254	            return null;
255	        }
256	        String trimmed = raw.trim();
257	        boolean hasCountryCode = trimmed.startsWith("+");
258	        // Strip spaces, dashes and brackets.
259	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
260	        String digits;
261	        if (hasCountryCode) {
262	            // Keep the explicit country code; drop the leading '+' for validation.
263	            digits = stripped.substring(1);
264	        } else {
265	            // No country code: assume '+61' and drop a single leading '0'.
266	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
267	            digits = "61" + national;
268	        }
269	        if (!digits.matches("\\d{8,15}")) {
270	            return null;
271	        }
272	        return "+" + digits;
273	    }
274	
275	    /**
276	     * Build the next customer code, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}.
277	     *
278	     * <p>{@code CITY3} is the upper-cased first three letters of {@code city} and
279	     * {@code LAST3} the upper-cased first three letters of {@code lastName} (fewer if
280	     * the value is shorter). {@code NNNN} is a per-city 4-digit zero-padded sequence
281	     * equal to one more than the number of owners already in that city
282	     * (e.g. {@code 'SYD-SMI-0007'}).
283	     */
284	    /**
285	     * Count the existing owners whose first and last name match the given names,
286	     * compared case-insensitively. Used to record an owner's namesake count at the
287	     * moment before it is created.
288	     */
289	    private int countNamesakes(String firstName, String lastName) {
290	        return (int) this.clinicService.findAllOwners().stream()
291	            .filter(existing -> existing.getFirstName() != null
292	                && existing.getFirstName().equalsIgnoreCase(firstName)
293	                && existing.getLastName() != null
294	                && existing.getLastName().equalsIgnoreCase(lastName))
295	            .count();
296	    }
297	
298	    private String nextCustomerCode(String city, String lastName) {
299	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
300	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
301	        int sequence = countOwnersInCity(city) + 1;
302	        return String.format("%s-%s-%04d", city3, last3, sequence);
303	    }
304	
305	    /**
306	     * Count the existing owners located in the given city, compared case-insensitively.
307	     * Used to derive the per-city 4-digit sequence in the customer code.
308	     */
309	    private int countOwnersInCity(String city) {
310	        return (int) this.clinicService.findAllOwners().stream()
311	            .filter(existing -> existing.getCity() != null
312	                && existing.getCity().equalsIgnoreCase(city))
313	            .count();
314	    }
315	
316	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
317	    @Override
318	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
319	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
320	        if (currentOwner == null) {
321	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
322	        }
323	        if (!normalizeEmail(ownerFieldsDto)) {
324	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
325	        }
326	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
327	        if (normalizedTelephone == null) {
328	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
329	        }
330	        currentOwner.setAddress(ownerFieldsDto.getAddress());
331	        currentOwner.setCity(ownerFieldsDto.getCity());
332	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
333	        currentOwner.setLastName(ownerFieldsDto.getLastName());
334	        currentOwner.setTelephone(normalizedTelephone);
335	        currentOwner.setEmail(ownerFieldsDto.getEmail());
336	        this.clinicService.saveOwner(currentOwner);
337	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
338	    }
339	
340	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
341	    @Transactional
342	    @Override
343	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
344	        Owner owner = this.clinicService.findOwnerById(ownerId);
345	        if (owner == null) {
346	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
347	        }
348	        this.clinicService.deleteOwner(owner);
349	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
350	    }
351	
352	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
353	    @Override
354	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
355	        Owner owner = this.clinicService.findOwnerById(ownerId);
356	        if (owner == null) {
357	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
358	        }
359	        HttpHeaders headers = new HttpHeaders();
360	        Pet pet = petMapper.toPet(petFieldsDto);
361	        owner.setId(ownerId);
362	        pet.setOwner(owner);
363	        pet.getType().setName(null);
364	        this.clinicService.savePet(pet);
365	        PetDto petDto = petMapper.toPetDto(pet);
366	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
367	            .buildAndExpand(pet.getId()).toUri());
368	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
369	    }
370	
371	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
372	    @Override
373	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
374	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
375	        if (currentOwner != null) {
376	            Pet currentPet = this.clinicService.findPetById(petId);
377	            if (currentPet != null) {
378	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
379	                currentPet.setName(petFieldsDto.getName());
380	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
381	                this.clinicService.savePet(currentPet);
382	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
383	            }
384	        }
385	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
386	    }
387	
388	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
389	    @Override
390	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
391	        HttpHeaders headers = new HttpHeaders();
392	        Visit visit = visitMapper.toVisit(visitFieldsDto);
393	        Pet pet = new Pet();
394	        pet.setId(petId);
395	        visit.setPet(pet);
396	        this.clinicService.saveVisit(visit);
397	        VisitDto visitDto = visitMapper.toVisitDto(visit);
398	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
399	            .buildAndExpand(visit.getId()).toUri());
400	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
401	    }
402	
403	
404	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
405	    @Override
406	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
407	        Owner owner = this.clinicService.findOwnerById(ownerId);
408	        if (owner != null) {
409	            Pet pet = owner.getPet(petId);
410	            if (pet != null) {
411	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
412	            }
413	        }
414	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
415	    }
416	}
